changeSet.sql:
CREATE OR REPLACE FUNCTION nexus.rdr229_restamp(p_table text) RETURNS text
LANGUAGE plpgsql SET search_path = pg_catalog, nexus AS $f$
DECLARE
    v_base   text := 'rdr229-stamp-' || p_table;
    v_n      integer;
    v_tail   text;
    v_done   timestamptz;
    v_orphan boolean;
    r        record;
    v_ms     bigint;
    v_step   bigint;
    v_blocks bigint;
    v_from   bigint;
    v_deadline timestamptz;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM nexus.data_moves m WHERE m.label = v_base) THEN
        RETURN 'not registered: ' || v_base || ' is not a registered stamp move';
    END IF;
    SELECT count(*) INTO v_n FROM nexus.data_moves m WHERE starts_with(m.label, v_base || '-rerun-');
    v_tail := CASE WHEN v_n = 0 THEN v_base ELSE v_base || '-rerun-' || v_n END;
    SELECT m.completed_at INTO v_done FROM nexus.data_moves m WHERE m.label = v_tail;
    IF v_done IS NULL THEN
        RETURN 'not registered: ' || v_tail || ' has not completed (it is open, paused or failed); nx doctor says which';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_constraint k
                    JOIN (VALUES
        ('catalog_collections', 'superseded_by', 'superseded_by_id', 'catalog_collections_superseded_by_id_check', 'SUPERSEDED'),
        ('chunks', 'collection', 'collection_id', 'chunks_collection_id_check', 'NAME_ID'),
        ('chunks', '-', 'collection_id', 'chunks_collection_id_not_null', 'NOT_NULL'),
        ('taxonomy_centroids', 'collection', 'collection_id', 'taxonomy_centroids_collection_id_check', 'NAME_ID'),
        ('taxonomy_centroids', '-', 'collection_id', 'taxonomy_centroids_collection_id_not_null', 'NOT_NULL'),
        ('catalog_document_chunks', 'collection', 'collection_id', 'catalog_document_chunks_collection_id_check', 'NAME_ID'),
        ('chunk_orphaned_at', 'collection', 'collection_id', 'chunk_orphaned_at_collection_id_check', 'NAME_ID'),
        ('topic_assignments', 'source_collection', 'source_collection_id', 'topic_assignments_source_collection_id_check', 'NAME_ID'),
        ('document_aspects', 'collection', 'collection_id', 'document_aspects_collection_id_check', 'NAME_ID'),
        ('topics', 'collection', 'collection_id', 'topics_collection_id_check', 'NAME_ID'),
        ('taxonomy_meta', 'collection', 'collection_id', 'taxonomy_meta_collection_id_check', 'NAME_ID'),
        ('document_highlights', 'collection', 'collection_id', 'document_highlights_collection_id_check', 'NAME_ID'),
        ('canary_query_ring', 'collection', 'collection_id', 'canary_query_ring_collection_id_check', 'NAME_ID'),
        ('aspect_extraction_queue', 'collection', 'collection_id', 'aspect_extraction_queue_collection_id_check', 'NAME_ID'),
        ('catalog_documents', 'physical_collection', 'physical_collection_id', 'catalog_documents_physical_collection_id_check', 'NAME_ID'),
        ('chash_remap', 'source_collection', 'source_collection_id', 'chash_remap_source_collection_id_check', 'NAME_ID'),
        ('chash_remap', 'target_collection', 'target_collection_id', 'chash_remap_target_collection_id_check', 'NAME_ID'),
        ('pdf_pipeline', 'collection', 'collection_id', 'pdf_pipeline_collection_id_check', 'NAME_ID'),
        ('reembed_jobs', 'source_collection', 'source_collection_id', 'reembed_jobs_source_collection_id_check', 'NAME_ID'),
        ('reembed_jobs', 'target_collection', 'target_collection_id', 'reembed_jobs_target_collection_id_check', 'NAME_ID')
                    ) AS t(tbl, name_column, id_column, conname, kind) ON t.conname = k.conname
                   WHERE t.tbl = p_table AND k.conrelid = to_regclass('nexus.' || quote_ident(p_table)) AND NOT k.convalidated) THEN
        RETURN 'not registered: no CHECK of ' || p_table || ' is NOT VALID (or the table has none), so there is nothing to finish';
    END IF;
    v_ms := COALESCE(NULLIF(current_setting('nexus.rdr229_restamp_probe_ms', true), '')::bigint, 60000);
    v_step := GREATEST(COALESCE(NULLIF(current_setting('nexus.rdr229_restamp_probe_blocks', true), '')::bigint, 8192), 1);
    v_deadline := clock_timestamp() + v_ms * interval '1 millisecond';
    SELECT max(pg_relation_size(pt.relid) / current_setting('block_size')::bigint) INTO v_blocks
      FROM pg_partition_tree(to_regclass('nexus.' || quote_ident(p_table))) pt WHERE pt.isleaf;
    v_blocks := COALESCE(v_blocks, pg_relation_size(to_regclass('nexus.' || quote_ident(p_table))) / current_setting('block_size')::bigint);
    FOR r IN SELECT DISTINCT t.name_column, t.id_column
               FROM (VALUES
        ('catalog_collections', 'superseded_by', 'superseded_by_id', 'catalog_collections_superseded_by_id_check', 'SUPERSEDED'),
        ('chunks', 'collection', 'collection_id', 'chunks_collection_id_check', 'NAME_ID'),
        ('chunks', '-', 'collection_id', 'chunks_collection_id_not_null', 'NOT_NULL'),
        ('taxonomy_centroids', 'collection', 'collection_id', 'taxonomy_centroids_collection_id_check', 'NAME_ID'),
        ('taxonomy_centroids', '-', 'collection_id', 'taxonomy_centroids_collection_id_not_null', 'NOT_NULL'),
        ('catalog_document_chunks', 'collection', 'collection_id', 'catalog_document_chunks_collection_id_check', 'NAME_ID'),
        ('chunk_orphaned_at', 'collection', 'collection_id', 'chunk_orphaned_at_collection_id_check', 'NAME_ID'),
        ('topic_assignments', 'source_collection', 'source_collection_id', 'topic_assignments_source_collection_id_check', 'NAME_ID'),
        ('document_aspects', 'collection', 'collection_id', 'document_aspects_collection_id_check', 'NAME_ID'),
        ('topics', 'collection', 'collection_id', 'topics_collection_id_check', 'NAME_ID'),
        ('taxonomy_meta', 'collection', 'collection_id', 'taxonomy_meta_collection_id_check', 'NAME_ID'),
        ('document_highlights', 'collection', 'collection_id', 'document_highlights_collection_id_check', 'NAME_ID'),
        ('canary_query_ring', 'collection', 'collection_id', 'canary_query_ring_collection_id_check', 'NAME_ID'),
        ('aspect_extraction_queue', 'collection', 'collection_id', 'aspect_extraction_queue_collection_id_check', 'NAME_ID'),
        ('catalog_documents', 'physical_collection', 'physical_collection_id', 'catalog_documents_physical_collection_id_check', 'NAME_ID'),
        ('chash_remap', 'source_collection', 'source_collection_id', 'chash_remap_source_collection_id_check', 'NAME_ID'),
        ('chash_remap', 'target_collection', 'target_collection_id', 'chash_remap_target_collection_id_check', 'NAME_ID'),
        ('pdf_pipeline', 'collection', 'collection_id', 'pdf_pipeline_collection_id_check', 'NAME_ID'),
        ('reembed_jobs', 'source_collection', 'source_collection_id', 'reembed_jobs_source_collection_id_check', 'NAME_ID'),
        ('reembed_jobs', 'target_collection', 'target_collection_id', 'reembed_jobs_target_collection_id_check', 'NAME_ID')
                    ) AS t(tbl, name_column, id_column, conname, kind)
              WHERE t.tbl = p_table AND t.kind = 'NAME_ID'
    LOOP
        v_from := 0;
        LOOP
            IF clock_timestamp() >= v_deadline THEN
                RETURN 'not registered: the orphan probe of ' || p_table || ' did not finish within ' || v_ms || ' ms (' || LEAST(v_from, v_blocks)
                    || ' of ' || v_blocks || ' blocks read); nothing was registered. Run it again, or give this session a longer bound first: '
                    || 'SET nexus.rdr229_restamp_probe_ms = ' || (v_ms * 5) || ';';
            END IF;
            EXECUTE format('SELECT EXISTS (SELECT 1 FROM nexus.%1$I t WHERE t.ctid >= %4$L::tid AND t.ctid < %5$L::tid '
                           'AND NULLIF(t.%2$I, '''') IS NOT NULL AND t.%3$I IS NULL '
                           'AND NOT EXISTS (SELECT 1 FROM nexus.catalog_collections cc WHERE cc.tenant_id = t.tenant_id AND cc.name = t.%2$I))',
                           p_table, r.name_column, r.id_column, '(' || v_from || ',0)', '(' || (v_from + v_step) || ',0)') INTO v_orphan;
            IF v_orphan THEN
                RETURN 'not registered: ' || p_table || ' still has an orphan row (a ' || r.name_column || ' that names no registry row of its tenant); '
                    || 'register that collection or delete the row, then run this again';
            END IF;
            v_from := v_from + v_step;
            EXIT WHEN v_from >= v_blocks;
        END LOOP;
    END LOOP;
    INSERT INTO nexus.data_moves (label, template, driving_schema, driving_table, chunk_size, sleep_ms, statement_timeout_ms,
                                  verification, on_complete, changeset_id, supersedes)
    SELECT v_base || '-rerun-' || (v_n + 1), b.template, b.driving_schema, b.driving_table, b.chunk_size, b.sleep_ms,
           b.statement_timeout_ms, b.verification, b.on_complete, b.changeset_id, v_tail
      FROM nexus.data_moves b WHERE b.label = v_base;
    RETURN 'registered: ' || v_base || '-rerun-' || (v_n + 1);
END
$f$;
REVOKE ALL ON FUNCTION nexus.rdr229_restamp(text) FROM PUBLIC;
